contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 seedAmount) public payable {
        uint256 drugsBefore = c.marketDrugs();
        bool initializedBefore = c.initialized();

        bool reverted;
        try c.seedMarket(seedAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(c.initialized() == initializedBefore && c.marketDrugs() == drugsBefore);
        } else {
            assert(c.initialized() == true && c.marketDrugs() == seedAmount);
        }
    }

    receive() external payable {}
}

