contract InvMutTest {
    C c;
    uint256 constant STARTING_KILOS = 300;
    uint256 constant DRUGS_TO_PRODUCE_1KILO = 86400;

    constructor(C _c) {
        c = _c;
    }

    function run(address ref, uint256 seedAmount) public payable {
        require(address(this).balance >= 1 ether, "need seed ether");
        // initialize market
        c.seedMarket{value: 1 ether}(seedAmount);
        require(c.initialized(), "seed failed");

        // give msg.sender a free kilo so Kilos[msg.sender] > 0
        c.getFreeKilo();
        uint256 kiloBefore = c.Kilos(address(this));
        require(kiloBefore == STARTING_KILOS, "free kilo not granted");

        // remember the ref's kilo count before collect
        uint256 refKiloBefore = c.Kilos(ref);

        // let some time pass (advance block.timestamp) -- can't do with cheatcodes, so rely on at least 1 second if possible
        // call collectDrugs, which updates Kilos[msg.sender]
        c.collectDrugs(ref);

        uint256 kiloAfter = c.Kilos(address(this));

        // compute the expected increment based on reported claimedDrugs and time-based production
        // getMyDrugs returns claimedDrugs + (secondsPassed * Kilos)
        uint256 drugsAvailable = c.getMyDrugs();
        uint256 expectedNewKilo = drugsAvailable / DRUGS_TO_PRODUCE_1KILO;

        assert(kiloAfter == kiloBefore + expectedNewKilo);
    }

    receive() external payable {}
}

