contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address ref, uint256 seedAmount) public payable {
        require(ref != address(0), "ref zero");
        require(ref != address(this), "ref self");
        require(address(this).balance >= seedAmount, "balance too low");

        // seed the market so collectDrugs can run
        c.seedMarket{value: seedAmount}(seedAmount);

        // give this test contract a kilo so it can be the caller of collectDrugs
        c.getFreeKilo();

        uint256 beforeRefClaimed = c.claimedDrugs(ref);
        uint256 beforeCallerDrugs = c.getMyDrugs();

        // deciding call
        c.collectDrugs(ref);

        uint256 afterRefClaimed = c.claimedDrugs(ref);

        // referrer should have received at least floor(beforeCallerDrugs / 5)
        uint256 expectedMin = beforeCallerDrugs / 5;

        assert(afterRefClaimed >= beforeRefClaimed + expectedMin);
    }

    receive() external payable {}
}

